// Desk light quality index — record JAH-GPC-SCREENBAR-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"cri": 95, "lux": 500};
var value = (m.cri*m.lux/100);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-SCREENBAR-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-SCREENBAR-000001|' + value.toFixed(2) + ' light quality index');

